#!/usr/bin/env bash
# Pin the NVIDIA providers to the versions in your NemoClaw bundle's mirror (they are pre-releases, which OpenTofu
# only selects when pinned exactly), by writing providers_override.tf next to main.tf. Re-run after a new bundle.
#   ./pin-providers.sh <bundle dir>      e.g. ./pin-providers.sh ~/nemoclaw/bundle
set -euo pipefail
mirror=${1:?usage: pin-providers.sh <bundle dir>}/providers/registry.opentofu.org
version() { ls "$mirror/$1" | sort -V | tail -1; }
cat > "$(dirname "$0")/providers_override.tf" <<HCL
# Generated by pin-providers.sh from $mirror; not committed.
terraform {
  required_providers {
    openshell = { source = "registry.opentofu.org/nvidia/openshell", version = "$(version nvidia/openshell)" }
    fabric    = { source = "registry.opentofu.org/nvidia/fabric", version = "$(version nvidia/fabric)" }
  }
}
HCL
echo "pinned: openshell $(version nvidia/openshell), fabric $(version nvidia/fabric)"
